            `> Roux: ${info.rain.version} (${info.rain.loader.name} ${info.rain.loader.version})`,
            `> Discord: ${info.discord.version} (${info.discord.build})`,
            `> React: ${info.react.version} (RN ${info.react.nativeVersion})`,
