            `> Sistema: ${info.os.name} ${info.os.version} ${info.os.sdk ? `(SDK ${info.os.sdk})` : ""}`.trimEnd(),
            `> Dispositivo: ${info.device.model}`,
        ].join("\n");

        if (ephemeral?.value) {
