import { useSettings } from "@api/settings";
import { findByProps } from "@metro";
import { ScrollView } from "react-native";

const {
    Stack,
    TableRadioGroup,
    TableRadioRow,
    TableRowGroup,
    TableSwitchRow,
} = findByProps("TableRow");

const SETTINGS_POSITIONS = [
    { key: "TOP", label: "En la parte superior de la página de ajustes" },
    { key: "ACCOUNT", label: "Sobre la configuración de pagos" },
    { key: "APPEARANCE", label: "Sobre la configuración de soporte" },
];

const INFO_OPTIONS = [
    { key: "PRESS", label: "Abrir información al pulsar la tarjeta" },
    { key: "BUTTON", label: "Mostrar botón de información del plugin" },
];

export default function SettingsPage() {
    const { settingsPosition, pluginCard, compactMode, updateSettings } = useSettings();

    return (
        <ScrollView style={{ flex: 1 }}>
            <Stack style={{ paddingVertical: 24, paddingHorizontal: 12 }} spacing={24}>
                <TableRowGroup title="Visualización">
                    <TableSwitchRow
                        label="Modo compacto"
                        subLabel="Mostrar plugins y temas en una vista de lista compacta"
                        value={compactMode}
                        onValueChange={(value: boolean) => updateSettings({ compactMode: value })}
                    />
                </TableRowGroup>

                <TableRadioGroup
                    title="Posición de ajustes"
                    titleStyle={{ marginTop: 5 }}
                    value={settingsPosition ?? "TOP"}
                    onChange={(value: string) => updateSettings({ settingsPosition: value })}
                >
                    {SETTINGS_POSITIONS.map(pos => (
                        <TableRadioRow
                            key={pos.key}
                            label={pos.label}
                            value={pos.key}
                        />
                    ))}
                </TableRadioGroup>

                <TableRadioGroup
                    title="Información de la tarjeta del plugin"
                    value={pluginCard?.showInfoButton ? "BUTTON" : pluginCard?.openOnPress ? "PRESS" : "NONE"}
                    onChange={(value: string) => updateSettings({
                        pluginCard: {
                            ...pluginCard,
                            showInfoButton: value === "BUTTON",
                            openOnPress: value === "PRESS"
                        }
                    })}
                >
                    {INFO_OPTIONS.map(opt => (
                        <TableRadioRow
                            key={opt.key}
                            label={opt.label}
                            value={opt.key}
                        />
                    ))}
                </TableRadioGroup>
            </Stack>
        </ScrollView>
    );
}

