    id: "animatedprofiles",
    version: "1.0.0",
    start() {
        const { mode } = useAnimatedProfilesSettings.getState();
        const isBGEnabled = () => mode === AnimatedProfilesMode.Both || mode === AnimatedProfilesMode.UserBGOnly;
