import SettingsTextInput from "@api/ui/components/SettingsTextInput";
import { findByProps } from "@metro";
import { Stack, TableRow, TableRowGroup, TableSwitchRow } from "@metro/common/components";
import { useEffect, useState } from "react";
import { ScrollView, Text } from "react-native";

import { fetchZiplinePublicDomains } from "./api/zipline";
import { useUploaderSettings } from "./storage";

const { Card } = findByProps("Card");
const { showSimpleActionSheet } = findByProps("showSimpleActionSheet");
const { hideActionSheet } = findByProps("openLazy", "hideActionSheet");

const UPLOAD_ACTIONS = [
    { label: "Copiar enlace al portapapeles", value: "clipboard" },
    { label: "Insertar solo en la entrada", value: "insertonly" },
    { label: "Insertar en la entrada y enviar", value: "insert" },
    { label: "Enviar en el siguiente mensaje", value: "nextmsg" },
];

const FILE_HOSTS = [
    { label: "Catbox", subLabel: "Los archivos se almacenan permanentemente, máx 200 MB", value: "catbox" },
    { label: "Litterbox", subLabel: "Los archivos expiran después de un tiempo, máx 1 GB", value: "litterbox" },
    { label: "Uguu", subLabel: "Los archivos se almacenan temporalmente, máx 128 MB, expiran en 3 h", value: "uguu" },
    { label: "Zipline", subLabel: "Instancia de host de archivos auto‑alojada", value: "zipline" },
];

const LITTERBOX_DURATIONS = [
    { label: "1 hora", value: "1" },
    { label: "12 horas", value: "12" },
    { label: "1 día", value: "24" },
    { label: "3 días", value: "72" },
];

const ZIPLINE_DURATIONS = [
    { label: "Nunca (por defecto)", value: "never" },
    { label: "1 hora", value: "1h" },
    { label: "12 horas", value: "12h" },
    { label: "1 día", value: "1d" },
    { label: "3 días", value: "3d" },
];

const ZIPLINE_FILENAMES = [
    { label: "Fecha (por defecto)", value: "date" },
    { label: "Aleatorio", value: "random" },
    { label: "UUID", value: "uuid" },
    { label: "Nombre del archivo", value: "name" },
    { label: "Nombre estilo Gfycat", value: "gfycat" },
];

function labelOf(options: { label: string; value: string }[], value: string): string {
    return options.find(o => o.value === value)?.label ?? value;
}

function openPicker(
    key: string,
    title: string,
    options: { label: string; value: string }[],
    current: string,
    onSelect: (v: string) => void,
) {
    showSimpleActionSheet({
        key,
        header: { title },
        options: options.map(({ label, value }) => ({
            label,
            isMarked: current === value,
            onPress: () => { onSelect(value); hideActionSheet(); },
        })),
    });
}

interface ZiplineDomainSectionProps {
    serverURL: string;
    selectedDomain: string;
    onSelectDomain: (d: string) => void;
}

function ZiplineDomainSection({ serverURL, selectedDomain, onSelectDomain }: ZiplineDomainSectionProps) {
    const [domains, setDomains] = useState<string[] | null>(null);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        if (!serverURL) {
            setDomains(null);
            return;
        }
        let cancelled = false;
        setLoading(true);
        fetchZiplinePublicDomains(serverURL).then(result => {
            if (!cancelled) {
                setDomains(result);
                setLoading(false);
            }
        });
        return () => { cancelled = true; };
    }, [serverURL]);

    if (!serverURL || (domains === null && !loading)) return null;

    if (loading) {
        return (
            <Text style={{ padding: 12, opacity: 0.5, fontSize: 13 }}>Obteniendo dominios...</Text>
        );
    }

    if (!domains || domains.length === 0) {
        return (
            <>
                <Text style={{ paddingHorizontal: 12, paddingBottom: 8, opacity: 0.6, fontSize: 13 }}>
                    No se encontraron sobrescrituras de dominio en este servidor.
                </Text>
                <Card>
                    <SettingsTextInput
                        placeholder="Introducir sobrescritura de dominio manualmente (opcional)"
                        value={selectedDomain}
                        onChange={onSelectDomain}
                        isClearable
                    />
                </Card>
            </>
        );
    }

    const openDomainPicker = () => {
        showSimpleActionSheet({
            key: "ZiplineDomainSelect",
            header: { title: "Seleccionar dominio" },
            options: [
                {
                    label: "Dominio predeterminado del servidor",
                    isMarked: selectedDomain === "",
                    onPress: () => { onSelectDomain(""); hideActionSheet(); },
                },
                ...domains.map(domain => ({
                    label: domain,
                    isMarked: selectedDomain === domain,
                    onPress: () => { onSelectDomain(domain); hideActionSheet(); },
                })),
            ],
        });
    };

    return (
        <TableRow
            label="Sobrescribir dominio"
            subLabel={selectedDomain || "Dominio predeterminado del servidor"}
            trailing={() => <TableRow.Arrow />}
            onPress={openDomainPicker}
        />
    );
}

export default function UploaderSettings() {
    const settings = useUploaderSettings();
    const { updateSettings } = settings;

    return (
        <ScrollView style={{ flex: 1 }}>
            <Stack style={{ paddingVertical: 12, paddingHorizontal: 12 }}>
                <TableRowGroup title="Ajustes">
                    <TableSwitchRow
                        label="Subir siempre"
                        subLabel="Subir al servicio incluso si está bajo el límite"
                        value={settings.alwaysUpload}
                        onValueChange={(v: boolean) => updateSettings({ alwaysUpload: v })}
                    />
                    <TableSwitchRow
                        label="Usar hipervínculo"
                        subLabel="Usar un hipervínculo markdown para que el nombre del archivo se muestre en el chat"
                        value={settings.useHyperlink}
                        onValueChange={(v: boolean) => updateSettings({ useHyperlink: v })}
                    />
                    <TableRow
                        label="Acción de subida"
                        subLabel={labelOf(UPLOAD_ACTIONS, settings.uploadAction || "clipboard")}
                        trailing={() => <TableRow.Arrow />}
                        onPress={() => openPicker(
                            "UploadActionSelect",
                            "Acción de subida",
                            UPLOAD_ACTIONS,
                            settings.uploadAction || "clipboard",
                            v => updateSettings({ uploadAction: v as typeof settings.uploadAction }),
                        )}
                    />
                    <TableRow
                        label="Host de archivos"
                        subLabel={labelOf(FILE_HOSTS, settings.selectedHost)}
                        trailing={() => <TableRow.Arrow />}
                        onPress={() => openPicker(
                            "FileHostSelect",
                            "Host de archivos",
                            FILE_HOSTS,
                            settings.selectedHost,
                            v => updateSettings({ selectedHost: v as typeof settings.selectedHost }),
                        )}
                    />
                </TableRowGroup>

                {settings.selectedHost === "catbox" && (
                    <TableRowGroup title="Catbox">
                        <Card>
                            <SettingsTextInput
                                placeholder="Tu hash de usuario de Catbox (opcional)"
                                value={settings.userHash}
                                onChange={(v: string) => updateSettings({ userHash: v })}
                                isClearable
                            />
                        </Card>
                    </TableRowGroup>
                )}

                {settings.selectedHost === "litterbox" && (
                    <TableRowGroup title="Litterbox">
                        <TableRow
                            label="Expiración"
                            subLabel={labelOf(LITTERBOX_DURATIONS, settings.litterboxDuration)}
                            trailing={() => <TableRow.Arrow />}
                            onPress={() => openPicker(
                                "LitterboxExpirySelect",
                                "Expiración de Litterbox",
                                LITTERBOX_DURATIONS,
                                settings.litterboxDuration,
                                v => updateSettings({ litterboxDuration: v }),
                            )}
                        />
                    </TableRowGroup>
                )}

                {settings.selectedHost === "zipline" && (
                    <>
                        <TableRowGroup title="Autenticación Zipline">
                            <Stack spacing={5}>
                                <Card>
                                    <SettingsTextInput
                                        placeholder="URL del servidor (p. ej., https://tu-zipline.com)"
                                        value={settings.ziplineServerURL}
                                        onChange={(v: string) => updateSettings({ ziplineServerURL: v })}
                                        isClearable
                                    />
                                </Card>
                                <Card>
                                    <SettingsTextInput
                                        placeholder="Tu token de Zipline"
                                        value={settings.ziplineUserToken}
                                        onChange={(v: string) => updateSettings({ ziplineUserToken: v })}
                                        isClearable
                                    />
                                </Card>
                            </Stack>
                        </TableRowGroup>

                        {settings.ziplineServerURL && <TableRowGroup title="Ajustes de subida Zipline">
                            <TableRow
                                label="Expiración del archivo"
                                subLabel={labelOf(ZIPLINE_DURATIONS, settings.ziplineDuration)}
                                trailing={() => <TableRow.Arrow />}
                                onPress={() => openPicker(
                                    "ZiplineExpirySelect",
                                    "Expiración del archivo",
                                    ZIPLINE_DURATIONS,
                                    settings.ziplineDuration,
                                    v => updateSettings({ ziplineDuration: v }),
                                )}
                            />
                            <TableRow
                                label="Formato del nombre del archivo"
                                subLabel={labelOf(ZIPLINE_FILENAMES, settings.ziplineFileNameFormat)}
                                trailing={() => <TableRow.Arrow />}
                                onPress={() => openPicker(
                                    "ZiplineFilenameSelect",
                                    "Formato del nombre del archivo",
                                    ZIPLINE_FILENAMES,
                                    settings.ziplineFileNameFormat,
                                    v => updateSettings({ ziplineFileNameFormat: v }),
                                )}
                            />
                            <ZiplineDomainSection
                                serverURL={settings.ziplineServerURL}
                                selectedDomain={settings.ziplineDomain}
                                onSelectDomain={(d: string) => updateSettings({ ziplineDomain: d })}
                            />
                        </TableRowGroup>}
                    </>
                )}
            </Stack>
        </ScrollView>
    );
}

