                            label={"Ocultar " + label}
                            disabled={settings.hidePaymentSettings}
                            value={settings.hidePaymentSettings || settings[key]}
                            onValueChange={value => settings.updateSettings({ [key]: value })}
                        />
                    ))}
                </TableRowGroup>
            </Stack>
        </ScrollView>
    );
}

