                        return (
                            <TableRow
                                key={decoration.hash}
                                label={decoration.alt}
                                icon={<TableRow.Icon source={findAssetId("ic_reaction_smile")} />}
                                disabled={isDisabled}
                                onPress={() => selectDecoration(isSelected ? null : decoration)}
                                trailing={isSelected
                                    ? () => <Text style={[TextStyleSheet["text-sm/normal"], { color: semanticColors.TEXT_MUTED }]}>Activa</Text>
