                    subLabel={
                        selectedDecoration?.presetId
                            ? `Preset actual: ${decorPreset?.name ?? "Desconocido"}`
                            : "Explora los presets de decoración"
                    }
                    icon={<TableRow.Icon source={findAssetId("ReactionIcon")} />}
                    arrow
                    disabled={isDisabled}
                    trailing={loadingTrailing ?? TableRow.Arrow}
                    onPress={() =>
                        navigation.push("RAIN_CUSTOM_PAGE", {
                            title: "Presets",
                            render: Presets,
                        })
                    }
                />

                <TableRow
                    label={
                        hasPendingDecoration
                            ? "Decoración en Revisión"
                            : "Enviar Nueva Decoración"
                    }
                    subLabel={
                        hasPendingDecoration
                            ? "Tu envío está a la espera de aprobación. No puedes enviar otro hasta que sea revisado."
                            : "Envía tu propia decoración personalizada para su revisión"
                    }
                    icon={
                        <TableRow.Icon
                            source={findAssetId(
                                hasPendingDecoration ? "ic_warning_24px" : "ic_add_24px"
                            )}
                            variant={hasPendingDecoration ? "danger" : undefined}
                        />
                    }
                    disabled={isDisabled || hasPendingDecoration}
                    arrow={!hasPendingDecoration}
                    onPress={() =>
                        navigation.push("RAIN_CUSTOM_PAGE", {
                            title: "Enviar una Decoración",
                            render: Submitoin,
                        })
                    }
                />

            </TableRowGroup>
        </View>
    );
}

