import { showToast } from "@api/ui/toasts";
import { findByProps } from "@metro";
import { ReactNative as RN } from "@metro/common";
import React from "react";

import { Emojis } from "../../modules";

const { TableRow: TR } = findByProps("TableRow");

export default function AddToServerRow({ guild, emoji, emojiName }: { guild: any, emoji: any, emojiName: string }) {
    const emojiSlotModule = findByProps("getMaxEmojiSlots");
    const EmojiStore = findByProps("getGuilds");

    const [isLoading, setIsLoading] = React.useState(false);

    const isSlotsUnknown = React.useRef(false);
    const slotsAvailable = React.useMemo(() => {
        let maxSlots = guild.getMaxEmojiSlots?.() ?? emojiSlotModule?.getMaxEmojiSlots?.(guild);
        if (!maxSlots) {
            if (!isSlotsUnknown.current) {
                isSlotsUnknown.current = true;
                showToast("No se pudo comprobar el número máximo de slots de emojis");
            }
            maxSlots = 250;
        }
        const guildEmojis = EmojiStore?.getGuilds?.()[guild.id]?.emojis ?? [];
        const isAnimated = emoji.src?.includes?.(".gif");
        return guildEmojis.filter((e: any) => e?.animated === isAnimated).length < maxSlots;
    }, [guild, emoji]);

    const handleAddToServer = async () => {
        if (!emojiName || isLoading || !slotsAvailable) return;
        setIsLoading(true);
        try {
            const response = await fetch(emoji.src);
            const blob = await response.blob();
            const reader = new FileReader();
            reader.readAsDataURL(blob);
            reader.onloadend = async () => {
                const base64data = reader.result as string;
                try {
                    await Emojis.uploadEmoji({
                        guildId: guild.id,
                        image: base64data,
                        name: emojiName,
                        roles: undefined
                    });
                    showToast(`Añadido ${emojiName} a ${guild.name}`);
                } catch (err: any) {
                    showToast("No se pudo añadir el emoji: " + (typeof err === "object" && err && "message" in err ? err.message : String(err)));
                } finally {
                    setIsLoading(false);
                }
            };
        } catch (e) {
            showToast("No se pudo añadir el emoji");
            setIsLoading(false);
        }
    };

    return (
        <TR
            disabled={!slotsAvailable}
            label={guild.name}
            subLabel={!slotsAvailable ? "No hay slots disponibles" : isSlotsUnknown.current ? "No se pudo comprobar el número máximo de slots de emojis" : undefined}
            icon={
                guild.icon ? (
                    <RN.Image
                        source={{ uri: `https://cdn.discordapp.com/icons/${guild.id}/${guild.icon}.png?size=64` }}
                        style={{ width: 40, height: 40, borderRadius: 8 }}
                    />
                ) : (
                    <RN.View style={{ width: 40, height: 40, borderRadius: 8, backgroundColor: "#5865F2", alignItems: "center", justifyContent: "center" }}>
                        <RN.Text style={{ color: "#fff", fontSize: 12, fontWeight: "bold" }}>{guild.acronym}</RN.Text>
                    </RN.View>
                )
            }
            onPress={handleAddToServer}
        />
    );
}

import { showToast } from "@api/ui/toasts";
import { clipboard, ReactNative } from "@metro/common";
import { Button } from "@metro/common/components";

import { downloadMediaAsset, LazyActionSheet } from "../../modules";
import { useExpressionUtilsSettings } from "../../storage";
import { showAddToServerActionSheet } from "../sheets/AddToServerActionSheet";


export default function StealButtons({ emoji }: { emoji: any }) {
    const emojiName = emoji.alt ?? emoji.name ?? "emoji";
    let emojiId = emoji.id;
    if (!emojiId && typeof emoji.src === "string") {
        const match = emoji.src.match(/discordapp\.com\/emojis\/(\d+)\.(?:png|gif|webp)/);
        if (match) {
            emojiId = match[1];
        }
    }
    const settings = useExpressionUtilsSettings();

    async function saveImage() {
        await downloadMediaAsset(emoji.src, 0);
        if (LazyActionSheet && LazyActionSheet.hideActionSheet) LazyActionSheet.hideActionSheet();
    }

    async function copyImageToClipboard() {
        const response = await fetch(emoji.src);
        const blob = await response.blob();
        const reader = new FileReader();
        reader.readAsDataURL(blob);
        reader.onloadend = () => {
            const base64data = reader.result as string;
            clipboard.setString(base64data);
            showToast(`Copiado la imagen de ${emojiName} al portapapeles`);
        };
    }

    const buttons = [
        settings.showCloneButton && {
            text: "Añadir al servidor",
            callback: () => {
                showAddToServerActionSheet(emoji);
            }
        },
        settings.showDownloadButton && {
            text: `Guardar imagen en ${ReactNative.Platform.select({ android: "Descargas", default: "Rollo de cámara" })}`,
            callback: saveImage
        },
        settings.showCopyURLButton && {
            text: "Copiar URL del emoji",
            callback: () => {
                clipboard.setString(emoji.src);
                showToast("¡URL del emoji copiada!");
            }
        },
        settings.showCopyMarkdownButton && {
            text: "Copiar Markdown",
            callback: () => {
                if (emojiId) {
                    const markdown = `<${emoji.animated ? "a" : ""}:${emojiName}:${emojiId}>`;
                    clipboard.setString(markdown);
                    showToast("¡Markdown del emoji copiado!");
                } else if (emoji.native) {
                    clipboard.setString(emoji.native);
                    showToast("¡Carácter del emoji copiado!");
                } else {
                    showToast("Este emoji no se puede copiar como markdown.");
                }
            }
        },
        ...ReactNative.Platform.select({
            ios: [
                {
                    text: "Copiar imagen al portapapeles",
                    callback: copyImageToClipboard
                }
            ],
            default: []
        })
    ].filter(Boolean);

    return (
        <>
            {(buttons.filter(Boolean) as { text: string; callback: () => void }[]).map(({ text, callback }) => (
                <Button
                    key={text}
                    text={text}
                    onPress={callback}
                    style={{ marginTop: ReactNative.Platform.select({ android: 8, default: 12 }) }}
                />
            ))}
        </>
    );
}

