import { findAssetId } from "@api/assets";
import { after, instead } from "@api/patcher";
import { waitForHydration } from "@api/storage";
import { metro } from "@lib";
import { cyrb64Hash } from "@lib/utils/cyrb64";
import { findByName } from "@metro";
import { definePlugin } from "@plugins";
import { Developers } from "@rain/Developers";

import settings from "./settings";
import { hidecallbuttonsSettings, useHideCallButtonsSettings } from "./storage";

const patches: (() => boolean)[] = [];
const find = (filter: (m: any) => boolean) => {
    return metro.findExports(
        metro.factories.createSimpleFilter(
            filter,
            cyrb64Hash(new Error().stack!),
        ),
    );
};

export default definePlugin({
    name: "HideCallButtons",
    description: "Oculta los botones de llamada de los DMs, perfiles de usuario y VCs",
    author: [Developers.John],
    id: "hidecallbuttons",
    version: "1.0.0",
    async start() {
        waitForHydration(useHideCallButtonsSettings);
        let videoCallAsset = findAssetId("ic_video");
        let voiceCallAsset = findAssetId("ic_audio");
        const videoAsset = findAssetId("video");
        const callAsset = findAssetId("nav_header_connect");
        const videoAsset2 = findAssetId("VideoIcon");
        const callAsset2 = findAssetId("PhoneCallIcon");

        if (videoCallAsset === undefined) videoCallAsset = videoAsset2;
        if (voiceCallAsset === undefined) voiceCallAsset = callAsset2;

        const UserProfileActions = findByName("UserProfileActions", false);
        let SimplifiedUserProfileContactButtons = findByName(
            "SimplifiedUserProfileContactButtons",
            false,
        );
        if (SimplifiedUserProfileContactButtons === undefined)
            SimplifiedUserProfileContactButtons = findByName(
                "UserProfileContactButtons",
                false,
            );
        const PrivateChannelButtons = find(
            x => x?.type?.name === "PrivateChannelButtons",
        );
        const VideoButton = findByName("VideoButton", false);
        // User Profile
        if (UserProfileActions !== undefined) {
            patches.push(
                after("default", UserProfileActions, (_, component) => {
                    if (
                        !hidecallbuttonsSettings.upHideVideoButton &&
                        !hidecallbuttonsSettings.upHideVoiceButton
                    )
                        return;

                    let buttons =
                        component?.props?.children?.props?.children[1]?.props
                            ?.children;
                    if (buttons === undefined)
                        buttons =
                            component?.props?.children[1]?.props?.children;
                    if (buttons?.props?.children !== undefined)
                        buttons = buttons?.props?.children;
                    if (buttons === undefined) return;

                    for (const idx in buttons) {
                        const button = buttons[idx];
                        if (button?.props?.children !== undefined) {
                            const buttonContainer = button?.props?.children;
                            for (const idx2 in buttonContainer) {
                                const btn = buttonContainer[idx2];
                                if (
                                    (btn?.props?.icon === voiceCallAsset &&
                                        hidecallbuttonsSettings.upHideVoiceButton) ||
                                    (btn?.props?.icon === videoCallAsset &&
                                        hidecallbuttonsSettings.upHideVideoButton)
                                )
                                    delete buttonContainer[idx2];
                            }
                        }
                        if (button?.props?.IconComponent !== undefined) {
                            if (hidecallbuttonsSettings.upHideVoiceButton)
                                delete buttons[1];
                            if (hidecallbuttonsSettings.upHideVideoButton)
                                delete buttons[2];
                        }
                        if (
                            (button?.props?.icon === voiceCallAsset &&
                                hidecallbuttonsSettings.upHideVoiceButton) ||
                            (button?.props?.icon === videoCallAsset &&
                                hidecallbuttonsSettings.upHideVideoButton)
                        )
                            delete buttons[idx];
                    }
                }),
            );
        }
        // Simplified user profile
        patches.push(
            after(
                "default",
                SimplifiedUserProfileContactButtons,
                (_, component) => {
                    const buttons = component?.props?.children;
                    if (buttons === undefined) return;

                    if (hidecallbuttonsSettings.upHideVoiceButton)
                        delete buttons[1];

                    if (hidecallbuttonsSettings.upHideVideoButton)
                        delete buttons[2];
                },
            ),
        );

        // VC
        patches.push(
            instead("default", VideoButton, (args, orig) => {
                if (hidecallbuttonsSettings.hideVCVideoButton) return;

                return orig.apply(this, args);
            }),
        );

        // Tabs V2 DM Header
        patches.push(
            after("type", PrivateChannelButtons, (_, component) => {
                if (
                    !hidecallbuttonsSettings.dmHideCallButton &&
                    !hidecallbuttonsSettings.dmHideVideoButton
                )
                    return;

                let buttons = component?.props?.children;
                if (buttons === undefined) return;

                if (buttons[0]?.props?.accessibilityLabel !== undefined) {
                    if (hidecallbuttonsSettings.dmHideCallButton)
                        delete buttons[0];
                    if (hidecallbuttonsSettings.dmHideVideoButton)
                        delete buttons[1];

                    return;
                }
                if (buttons[0]?.props?.source === undefined)
                    buttons = buttons[0]?.props?.children;

                if (buttons === undefined) return;

                for (const idx in buttons) {
                    const button = buttons[idx];
                    if (
                        (button?.props?.source === callAsset &&
                            hidecallbuttonsSettings.dmHideCallButton) ||
                        (button?.props?.source === videoAsset &&
                            hidecallbuttonsSettings.dmHideVideoButton) ||
                        (button?.props?.source === callAsset2 &&
                            hidecallbuttonsSettings.dmHideCallButton) ||
                        (button?.props?.source === videoAsset2 &&
                            hidecallbuttonsSettings.dmHideVideoButton)
                    )
                        delete buttons[idx];
                }
            }),
        );
    },
    stop() {
        for (const unpatch of patches) unpatch();
    },
    settings: settings,
});

src/plugins/index.ts.code:
import { useSettings } from "@api/settings";
import { createFileStorage, waitForHydration } from "@api/storage";
import { showToast } from "@api/ui/toasts";
import { logger } from "@lib/utils/logger";
import { JSX } from "react";
import { create } from "zustand";
import { createJSONStorage, persist } from "zustand/middleware";

import * as t from "./types";

export const pluginInstances = new Map<string, t.rainPlugin>();
let _setupPromise: Promise<void> | null = null;

// these are the things we use to set how quickly plugins start
const BATCH_SIZE = 5;
const BATCH_DELAY_MS = 32;

interface PluginSettingsStore {
    settings: t.PluginSettingsStorage;
    _hasHydrated: boolean;
    updatePluginSetting: (id: string, enabled: boolean) => void;
    getPluginSetting: (id: string) => { enabled: boolean } | undefined;
    setHasHydrated: (state: boolean) => void;
}

export const usePluginSettings = create<PluginSettingsStore>()(
    persist(
        (set, get) => ({
            settings: {},
            _hasHydrated: false,
            updatePluginSetting: (id: string, enabled: boolean) => {
                set(state => ({
                    settings: {
                        ...state.settings,
                        [id]: { enabled },
                    },
                }));
            },
            getPluginSetting: (id: string) => get().settings[id],
            setHasHydrated: (state: boolean) => set({ _hasHydrated: state }),
        }),
        {
            name: "plugin-settings",
            storage: createJSONStorage(() => createFileStorage("plugins/settings.json")),
            onRehydrateStorage: () => state => {
                state?.setHasHydrated(true);
            },
        }
    )
);

export const pluginSettings = new Proxy({} as t.PluginSettingsStorage, {
    get: (_, prop: string) => usePluginSettings.getState().settings[prop],
    set: (_, prop: string, value: { enabled: boolean }) => {
        usePluginSettings.getState().updatePluginSetting(prop, value.enabled);
        return true;
    },
});

function assert<T>(condition: T, id: string, attempt: string): asserts condition {
    if (!condition) throw new Error(`[${id}] Attempted to ${attempt}`);
}

async function runPluginLifecycle(id: string, method: "start" | "eagerStart"): Promise<void> {
    const instance = pluginInstances.get(id);
    assert(instance, id, `run ${method} on unknown plugin`);

    const settings = useSettings.getState();
    if (settings.safeMode && !isPluginCore(id)) {
        logger.log(`[${id}] Skipped in safe mode`);
        return;
    }

    try {
        await instance[method]?.();
        usePluginSettings.getState().updatePluginSetting(id, true);
    } catch (error) {
        const errorMsg = `[${id}] Failed: ${error}`;
        method === "start" ? showToast(errorMsg) : console.error(errorMsg, error);
        throw error;
    }
}

export const startPlugin = (id: string): Promise<void> => runPluginLifecycle(id, "start");
export const startEagerPlugin = (id: string): Promise<void> => runPluginLifecycle(id, "eagerStart");

export async function stopPlugin(id: string): Promise<void> {
    const instance = pluginInstances.get(id);
    assert(instance, id, "stop a non-started plugin");

    try {
        await instance.stop?.();
        usePluginSettings.getState().updatePluginSetting(id, false);
    } catch (error) {
        console.error(`[${id}] Failed to stop:`, error);
        throw error;
    }
}

export const findPluginById = (id: string): boolean => pluginInstances.has(id);

export const isPluginCore = (id: string): boolean => id.startsWith("core");

export function isPluginEnabled(id: string): boolean {
    const setting = usePluginSettings.getState().settings[id];
    return setting?.enabled ?? isPluginCore(id);
}

function ensureSetup(): Promise<void> {
    if (_setupPromise) return _setupPromise;

    _setupPromise = (async () => {
        const [{ default: rainPlugins }] = await Promise.all([
            import("#rain-plugins"),
            waitForHydration(usePluginSettings),
        ]);

        for (const [id, plugin] of Object.entries(rainPlugins)) {
            const instance = plugin as t.rainPlugin;
            if (!instance) continue;

            instance.id = id;

            pluginInstances.set(id, instance);
        }
    })();

    return _setupPromise;
}

// tldr: plugins were causing discord to start slow as they made the load take longer even though they technically were lazy, so we now do this to let the app render :P
async function startBatched(ids: string[], method: "start" | "eagerStart"): Promise<void> {
    for (let i = 0; i < ids.length; i += BATCH_SIZE) {
        const batch = ids.slice(i, i + BATCH_SIZE);

        await Promise.allSettled(
            batch.map(async id => {
                try {
                    await (method === "start" ? startPlugin(id) : startEagerPlugin(id));
                } catch (error) {
                    logger.log(`Failed to ${method} ${id}:`, error);
                }
            })
        );

        if (i + BATCH_SIZE < ids.length) {
            await new Promise(resolve => setTimeout(resolve, BATCH_DELAY_MS));
        }
    }
}

export async function initPlugins(): Promise<void> {
    await ensureSetup();

    const ids = Array.from(pluginInstances.keys()).filter(isPluginEnabled);
    await startBatched(ids, "start");
}

export async function initEagerPlugins(): Promise<void> {
    await ensureSetup();

    const ids = Array.from(pluginInstances.keys()).filter(isPluginEnabled);
    await Promise.allSettled(
        ids.map(async id => {
            try { await startEagerPlugin(id); }
            catch (error) { logger.log(`Failed to eagerStart ${id}:`, error); }
        })
    );
}

export function definePlugin(instance: t.rainPlugin): t.rainPlugin {
    // @ts-expect-error
    instance[Symbol.for("rain.plugin")] = true;
    return instance;
}

export function getPluginSettingsComponent(id: string): (() => JSX.Element) | null {
    return pluginInstances.get(id)?.settings || null;
}

