import { findAssetId } from "@api/assets";
import { showToast } from "@api/ui/toasts";
import { React, ReactNative as RN } from "@metro/common";

import { SelfPresenceStore } from "../../../modules";
import { useMultiScrobblerSettings } from "../../../storage";
import { clearActivity } from "../../../utils/activity";
import { setStorage } from "../Settings";
import {
    ScrollView,
    Stack,
    TableRow,
    TableRowGroup,
    TextInput,
} from "./components/TableComponents";

export default function IgnoreListSettingsPage() {
    const settings = useMultiScrobblerSettings();
    const [newAppName, setNewAppName] = React.useState("");

    const checkAndClearIfIgnored = () => {
        const ignoredActivity = SelfPresenceStore.findActivity(act => {
            if (!act.name) return false;
            return settings.ignoreList.some((ignoredApp: string) =>
                act.name.toLowerCase().includes(ignoredApp.toLowerCase()),
            );
        });
        if (ignoredActivity) {
            clearActivity();
        }
    };

    const triggerImmediateUpdate = () => {
        import("../../../manager").then(({ updateActivity }) => {
            updateActivity();
        });
    };

    const addAppToIgnoreList = () => {
        if (!newAppName.trim()) {
            showToast("Por favor, introduce un nombre de aplicación", findAssetId("Small"));
            return;
        }

        if (!settings.ignoreList.includes(newAppName.trim())) {
            setStorage("ignoreList", [...settings.ignoreList, newAppName.trim()]);
            setNewAppName("");
            showToast("Aplicación agregada a la lista de ignorados", findAssetId("Check"));
            checkAndClearIfIgnored();
        } else {
            showToast("La aplicación ya está en la lista de ignorados", findAssetId("Warning"));
        }
    };

    const removeAppFromIgnoreList = (appName: string) => {
        setStorage(
            "ignoreList",
            settings.ignoreList.filter((app: string) => app !== appName),
        );
        showToast("Aplicación eliminada de la lista de ignorados", findAssetId("Check"));
        triggerImmediateUpdate();
    };

    return (
        <ScrollView style={{ flex: 1 }} contentContainerStyle={{ padding: 10 }}>
            <Stack spacing={8}>
                <TableRowGroup title="Agregar aplicación a ignorar">
                    <Stack spacing={4}>
                        <TextInput
                            placeholder="Introduce el nombre de la aplicación"
                            value={newAppName}
                            onChange={setNewAppName}
                            isClearable
                            onSubmitEditing={addAppToIgnoreList}
                            returnKeyType="done"
                        />
                    </Stack>
                </TableRowGroup>

                <TableRowGroup>
                    <TableRow
                        label="Agregar a la lista de ignorados"
                        subLabel="Agregar el nombre de la aplicación actual a tu lista de ignorados"
                        trailing={<TableRow.Arrow />}
                        onPress={addAppToIgnoreList}
                    />
                </TableRowGroup>

                {settings.ignoreList.length > 0 && (
                    <TableRowGroup title="Aplicaciones ignoradas">
                        {settings.ignoreList.map((appName: string, index: number) => (
                            <TableRow
                                key={index}
                                label={appName}
                                trailing={
                                    <RN.TouchableOpacity
                                        onPress={() => removeAppFromIgnoreList(appName)}
                                        style={{
                                            padding: 6,
                                            backgroundColor: "#ed4245",
                                            borderRadius: 8,
                                            justifyContent: "center",
                                            alignItems: "center",
                                        }}
                                    >
                                        <RN.Image
                                            source={findAssetId("TrashIcon")}
                                            style={{ width: 18, height: 18, tintColor: "#ffffff" }}
                                        />
                                    </RN.TouchableOpacity>
                                }
                            />
                        ))}
                    </TableRowGroup>
                )}

                <TableRowGroup title="Acerca de la lista de ignorados">
                    <TableRow
                        label="Cómo funciona"
                        subLabel="Cuando cualquier aplicación de tu lista de ignorados está activa, tu estado de música se ocultará"
                    />
                    <TableRow
                        label="Detección"
                        subLabel="Las aplicaciones se detectan por el nombre de su actividad en Discord"
                    />
                    <TableRow
                        label="Ejemplos"
                        subLabel="Spotify, YouTube Music, Kizzy, Metrolist, echo"
                    />
                </TableRowGroup>
            </Stack>
        </ScrollView>
    );
}

