import { findAssetId } from "@api/assets";
import { after, before } from "@api/patcher";
import { showToast } from "@api/ui/toasts";
import { findInReactTree } from "@lib/utils";
import { findByProps } from "@metro";
import { React } from "@metro/common";

import { useTextReplaceSettings } from "../storage";

const LazyActionSheet = findByProps("openLazy", "hideActionSheet");
const ActionSheetRow = findByProps("ActionSheetRow")?.ActionSheetRow;
const DownloadIcon = findAssetId("DownloadIcon");
const JSON_CODEBLOCK_PATTERN = /^```(?:json)\n([\s\S]*?)```$/gm;

export default function patchMessageLongPressActionSheet() {
    return before("openLazy", LazyActionSheet, ([component, key, msg]) => {
        if (key !== "MessageLongPressActionSheet") return;
        const content = msg?.message?.content;
        if (!content) return;

        component.then((instance: any) => {
            const unpatch = after("default", instance, (_, res) => {
                React.useEffect(() => {
                    return () => {
                        unpatch();
                    };
                }, []);

                const rules = [...content.matchAll(JSON_CODEBLOCK_PATTERN)]
                    .map(m => {
                        try {
                            return JSON.parse(m[1]);
                        } catch {
                            return null;
                        }
                    })
                    .filter(
                        r =>
                            r &&
                            typeof r.name === "string" &&
                            typeof r.match === "string" &&
                            typeof r.replace === "string",
                    );

                if (!rules.length) return;

                const buttons = findInReactTree(
                    res,
                    x => Array.isArray(x) && x.some(c => c?.type?.name === "ActionSheetRow"),
                );
                if (!buttons) return;

                rules.forEach((rule: any) => {
                    buttons.unshift(
                        <ActionSheetRow
                            label={`Importar regla: ${rule.name}`}
                            icon={<ActionSheetRow.Icon source={DownloadIcon} />}
                            onPress={() => {
                                LazyActionSheet.hideActionSheet();
                                const currentRules = useTextReplaceSettings.getState().rules;
                                useTextReplaceSettings.getState().updateSettings({ rules: [...currentRules, rule] });
                                showToast(`Regla importada: ${rule.name}`, DownloadIcon);
                            }}
                        />,
                    );
                });
            });
        });
    });
}

src/plugins/textreplace/patches/sendMess.code:
import { findAssetId } from "@api/assets";
import { before } from "@api/patcher";
import { showToast } from "@api/ui/toasts";
import { logger } from "@lib/utils/logger";
import { findByProps } from "@metro";

import { useTextReplaceSettings } from "../storage";

const Messages = findByProps("sendMessage", "receiveMessage");

const Warning = findAssetId("ic_warning_24px");

export default function patchSendMessage() {
    return before("sendMessage", Messages, args => {
        // Rules, but filtering out ones with empty match arguments
        const rules = useTextReplaceSettings.getState().rules.filter(rule => rule.match);
        // The message content
        let content = args[1].content as string;

        // Go through each rule and run the message through it
        for (const rule of rules) {
            // If the rule is a regular expression, do regex logic
            if (rule.regex) {
                try {
                    // Create regexp
                    const pattern = new RegExp(rule.match, rule.flags);
                    // Replace
                    content = content.replace(pattern, rule.replace);
                } catch (e) {
                    // Log error
                    logger.error(e);
                    // Notify user
                    showToast(`¡Error al usar RegExp para ${rule.name}!`, Warning);
                }
            } else {
                // Normal logic
                content = content.replaceAll(rule.match, rule.replace);
            }
        }

        // Update message content with the updated content
        args[1].content = content;
    });
}

