                                props: {
                                    IconComponent: () => (
                                        <FormIcon
                                            style={{ opacity: 1 }}
                                            source={findAssetId("ChatMarkUnreadIcon")}
                                        />
                                    ),
                                },
                            }}
                            onPress={() => {
                                LazyActionSheet.hideActionSheet();
                                Navigation.push(navigator);
                            }}
                            key="view-raw"
                        />
                    );

                    middleGroup.props.children.push(viewRawButton);
